const TOURS={evening:{name:'Evening Desert Safari',packages:[{id:'sharing',name:'Sharing',price:120,unit:'person'},{id:'private',name:'Private',price:650,unit:'vehicle'}]},morning:{name:'Morning Desert Safari',packages:[{id:'private',name:'Private',price:550,unit:'vehicle'}]},premium:{name:'Premium Desert Safari',packages:[{id:'sharing',name:'Sharing',price:220,unit:'person'},{id:'private',name:'Private',price:850,unit:'vehicle'}]},quad:{name:'Quad Bike Adventure',meetingPoint:true,packages:[{id:'bike',name:'1 Bike · 30 Minutes',price:150,unit:'bike'}]},canam2:{name:'Can-Am Buggy · 2 Seater',meetingPoint:true,packages:[{id:'buggy',name:'2 Seater · 30 Minutes',price:1000,unit:'buggy'}]},canam4:{name:'Can-Am Buggy · 4 Seater',meetingPoint:true,packages:[{id:'buggy',name:'4 Seater · 30 Minutes',price:1500,unit:'buggy'}]}};const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const menuBtn=$('#menuBtn'),nav=$('#mainNav');menuBtn?.addEventListener('click',()=>{nav.classList.toggle('open');menuBtn.setAttribute('aria-expanded',String(nav.classList.contains('open')))});$$('#mainNav a').forEach(a=>a.addEventListener('click',()=>nav.classList.remove('open')));$('#year').textContent=new Date().getFullYear();const cards=$$('.tour-card');function filterCards(type='all',query=''){cards.forEach(card=>{const cat=card.dataset.category||'',search=(card.dataset.search||'').toLowerCase();card.hidden=!((type==='all'||cat.includes(type))&&(!query||search.includes(query)))})}$$('[data-card-filter]').forEach(btn=>btn.addEventListener('click',()=>{$$('[data-card-filter]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');filterCards(btn.dataset.cardFilter,$('#tourSearch').value.trim().toLowerCase())}));$$('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{const type=btn.dataset.filter;const match=$(`[data-card-filter="${type}"]`);if(match)match.click();$('#tours').scrollIntoView({behavior:'smooth'})}));$('#tourSearch').addEventListener('input',e=>filterCards($('[data-card-filter].active')?.dataset.cardFilter||'all',e.target.value.trim().toLowerCase()));const modal=$('#bookingModal'),form=$('#bookingForm'),tourSelect=$('#bookingTour'),packageSelect=$('#bookingPackage'),qty=$('#bookingQty'),qtyLabel=$('#qtyLabel'),price=$('#bookingPrice'),pricingNote=$('#pricingNote'),pickupField=$('#pickupField'),pickup=$('#bookingPickup'),meetingPointNote=$('#meetingPointNote');let step=1;function populateTours(){tourSelect.innerHTML=Object.entries(TOURS).map(([id,t])=>`<option value="${id}">${t.name}</option>`).join('')}function currentPackage(){const t=TOURS[tourSelect.value];return t.packages.find(p=>p.id===packageSelect.value)||t.packages[0]}function populatePackages(){const t=TOURS[tourSelect.value];packageSelect.innerHTML=t.packages.map(p=>`<option value="${p.id}">${p.name} · AED ${p.price.toLocaleString()}</option>`).join('');updateBookingUI()}function updateBookingUI(){const t=TOURS[tourSelect.value],p=currentPackage(),unit=p.unit;qtyLabel.firstChild.textContent=unit==='person'?'Guests':unit==='bike'?'Number of bikes':unit==='buggy'?'Number of buggies':'Vehicles';if(unit==='vehicle')qty.value=1;const total=p.price*Math.max(1,Number(qty.value)||1);price.textContent=`AED ${total.toLocaleString()}`;pricingNote.textContent=`${p.name} · ${p.unit==='person'?'per person':p.unit==='vehicle'?'private vehicle rate':p.unit==='bike'?'per bike / 30 minutes':'per buggy / 30 minutes'}`;pickupField.style.display=t.meetingPoint?'none':'';meetingPointNote.textContent=t.meetingPoint?'This experience is direct to the meeting point. Phoenix Tours will confirm the exact location on WhatsApp.':'Pickup details will be confirmed according to your selected package.'}function setStep(n){step=Math.max(1,Math.min(4,n));$$('.form-step').forEach(x=>x.classList.toggle('active',Number(x.dataset.step)===step));$$('.progress span').forEach((x,i)=>x.classList.toggle('active',i<step));$('#prevStep').style.visibility=step===1?'hidden':'visible';$('#nextStep').classList.toggle('hidden',step===4);$('#submitBooking').classList.toggle('hidden',step!==4);if(step===4)renderReview()}function openBooking(tourId){modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';if(tourId&&TOURS[tourId])tourSelect.value=tourId;populatePackages();setStep(1);setTimeout(()=>tourSelect.focus(),80)}function closeBooking(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.body.style.overflow=''}populateTours();populatePackages();$$('[data-open-booking]').forEach(b=>b.addEventListener('click',()=>openBooking()));$$('[data-book-tour]').forEach(b=>b.addEventListener('click',()=>openBooking(b.dataset.bookTour)));$$('[data-close-booking]').forEach(b=>b.addEventListener('click',closeBooking));tourSelect.addEventListener('change',populatePackages);packageSelect.addEventListener('change',updateBookingUI);qty.addEventListener('input',updateBookingUI);const date=$('#bookingDate'),parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dubai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());date.min=['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-');function validCurrentStep(){const active=$(`.form-step[data-step="${step}"]`),fields=[...active.querySelectorAll('input[required],select[required]')];for(const f of fields){if(!f.reportValidity())return false}return true}$('#nextStep').addEventListener('click',()=>{if(validCurrentStep())setStep(step+1)});$('#prevStep').addEventListener('click',()=>setStep(step-1));function getBooking(){const t=TOURS[tourSelect.value],p=currentPackage(),q=Math.max(1,Number(qty.value)||1);return{id:`PX-${Date.now().toString().slice(-8)}`,createdAt:new Date().toISOString(),tourId:tourSelect.value,tour:t.name,package:p.name,unit:p.unit,quantity:q,total:p.price*q,date:date.value,time:$('#bookingTime').value,pickup:t.meetingPoint?'Direct meeting point':pickup.value.trim()||'To be confirmed',name:$('#bookingName').value.trim(),phone:$('#bookingPhone').value.trim(),email:$('#bookingEmail').value.trim(),notes:$('#bookingNotes').value.trim(),status:'New'}}function renderReview(){const b=getBooking();$('#bookingReview').innerHTML=`<dl><div><dt>Experience</dt><dd>${b.tour}</dd></div><div><dt>Package</dt><dd>${b.package}</dd></div><div><dt>Date</dt><dd>${b.date||'—'} · ${b.time}</dd></div><div><dt>${b.unit==='person'?'Guests':'Quantity'}</dt><dd>${b.quantity}</dd></div><div><dt>Pickup</dt><dd>${b.pickup}</dd></div><div><dt>Estimated total</dt><dd>AED ${b.total.toLocaleString()}</dd></div><div><dt>Name</dt><dd>${b.name||'—'}</dd></div><div><dt>Phone</dt><dd>${b.phone||'—'}</dd></div></dl>`}form.addEventListener('submit',e=>{e.preventDefault();if(!validCurrentStep())return;const b=getBooking(),saved=JSON.parse(localStorage.getItem('phoenixBookings')||'[]');saved.unshift(b);localStorage.setItem('phoenixBookings',JSON.stringify(saved.slice(0,200)));const msg=`Hello Phoenix Tours! I would like to request a booking.%0A%0ABooking ID: ${encodeURIComponent(b.id)}%0AExperience: ${encodeURIComponent(b.tour)}%0APackage: ${encodeURIComponent(b.package)}%0A${encodeURIComponent(b.unit==='person'?'Guests':'Quantity')}: ${b.quantity}%0ADate: ${encodeURIComponent(b.date)}%0ATime: ${encodeURIComponent(b.time)}%0APickup: ${encodeURIComponent(b.pickup)}%0AEstimated total: AED ${b.total}%0A%0AName: ${encodeURIComponent(b.name)}%0APhone: ${encodeURIComponent(b.phone)}%0AEmail: ${encodeURIComponent(b.email||'Not provided')}%0ANotes: ${encodeURIComponent(b.notes||'None')}%0A%0APlease confirm availability, final price, inclusions and pickup/meeting details.`;window.open(`https://wa.me/971561505270?text=${msg}`,'_blank','noopener');closeBooking();form.reset();qty.value=2;populatePackages()});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.classList.contains('open'))closeBooking()});